// Bakes the vocabulary the browser needs into two generated files, so the Vokabeln tab no longer
// downloads the authoring sources (vocab-n*.js, vocab-correction-rules.js, romaji layer: ~47 MB).
//   vocab-runtime.js          list fields of every merged entry (what app.js hydrate used to compute)
//   vocab-runtime-details.js  examples and notes per entry, loaded in the background
// Usage: node scripts/build-vocab-runtime.cjs [--check]
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const root = path.resolve(__dirname, '..');

const SOURCE_FILES = ['vocab-example-overrides.js', 'vocab-corrections.js', 'vocab-correction-rules.js',
  'vocab-romaji-hepburn.js', 'vocab-n5.js', 'vocab-n4.js', 'vocab-n3.js', 'vocab-n2.js', 'vocab-n1.js',
  'yojijukugo-data.js', 'idioms-data.js'];
const RUNTIME_FILE = 'vocab-runtime.js';
const DETAILS_FILE = 'vocab-runtime-details.js';
const DETAIL_FIELDS = ['examples', 'notes'];
// Authoring metadata and normalization bookkeeping that nothing reads at runtime.
const DROPPED_FIELDS = new Set(['correctionId', 'vocabularyBatch', 'editorialBatch', 'vocabularyCompletion',
  'conjugationReason', '__rawWord', '__rawReading', '__rawLevel', '__rawType', '__rawExamples', '__normalized',
  '__exampleOverrideApplied', 'studyLens', 'mergeKey']);
const HEADER = '// Generated by scripts/build-vocab-runtime.cjs from the vocabulary sources. Do not edit; run npm run build:vocab-runtime.\n';

// Mirrors the former sectionLoaders.vocab.hydrate in app.js: dedupe, normalize, merge.
function loadMergedVocabulary(readFile) {
  const c = { console }; c.window = c;
  for (const file of SOURCE_FILES) vm.runInNewContext(readFile(file), c, { filename: file });
  const app = readFile('app.js');
  const start = app.indexOf('  var INTENTIONAL_VOCAB_OVERLAP_KEYS'), end = app.indexOf('  var sectionLoaders');
  if (start === -1 || end === -1) throw new Error('app.js merge helpers not found');
  vm.runInNewContext(app.slice(start, end) +
    '\nwindow.__runtimeHelpers = { dedupeSpecialistItems, getEntryKey, mergeVocabSources };', c, { filename: 'app.js' });
  const h = c.__runtimeHelpers;
  const rawSources = [
    { name: 'vocab-n5', items: c.VOCAB_N5 || [] },
    { name: 'vocab-n4', items: c.VOCAB_N4 || [] },
    { name: 'vocab-n3', items: c.VOCAB_N3 || [] },
    { name: 'vocab-n2', items: c.VOCAB_N2 || [] },
    { name: 'vocab-n1', items: c.VOCAB_N1 || [] },
    { name: 'yojijukugo', items: h.dedupeSpecialistItems(c.YOJIJUKUGO_DATA || [], h.getEntryKey) },
    { name: 'idioms', items: c.IDIOMS_DATA || [] }
  ];
  const rules = c.VOCAB_CORRECTION_RULES || {};
  return {
    items: h.mergeVocabSources(c.getNormalizedVocabSources(rawSources)),
    completionRedirects: rules.completionRedirects || {}
  };
}

// getVocabularyPitchConfidence (section-configs.js) only reads evidence for the entry's own word and reading.
function runtimePitchProvenance(item) {
  if (!Array.isArray(item.pitchProvenance)) return item.pitchProvenance;
  return item.pitchProvenance
    .filter(entry => entry && entry.match && entry.match.word === item.word && entry.match.reading === item.reading)
    .map(entry => ({ match: { word: entry.match.word, reading: entry.match.reading }, patterns: entry.patterns }));
}

function splitItem(item) {
  const core = {}, details = {};
  for (const key of Object.keys(item)) {
    if (DROPPED_FIELDS.has(key) || item[key] === undefined) continue;
    if (DETAIL_FIELDS.includes(key)) details[key] = item[key];
    else core[key] = key === 'pitchProvenance' ? runtimePitchProvenance(item) : item[key];
  }
  return { core, details };
}

// One entry per line keeps git diffs of content batches readable.
function lines(values) {
  return values.map(value => JSON.stringify(value)).join(',\n');
}

function buildVocabRuntime(readFile = file => fs.readFileSync(path.join(root, file), 'utf8')) {
  const { items, completionRedirects } = loadMergedVocabulary(readFile);
  const parts = items.map(splitItem);
  return {
    [RUNTIME_FILE]: HEADER + 'window.VOCAB_RUNTIME = {\n"completionRedirects": ' + JSON.stringify(completionRedirects) +
      ',\n"items": [\n' + lines(parts.map(p => p.core)) + '\n]};\n',
    [DETAILS_FILE]: HEADER + '// Entries align by index with VOCAB_RUNTIME.items.\nwindow.VOCAB_RUNTIME_DETAILS = [\n' +
      lines(parts.map(p => p.details)) + '\n];\n'
  };
}

// A Windows checkout (core.autocrlf) may hold the generated files with CRLF line endings.
function staleFiles(files) {
  return Object.keys(files).filter(file => {
    const target = path.join(root, file);
    return !fs.existsSync(target) || fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n') !== files[file];
  });
}

// For writers outside the journaled import (legacy one-off scripts): rebuild after writing sources.
function writeVocabRuntime() {
  const files = buildVocabRuntime();
  const stale = staleFiles(files);
  for (const file of stale) fs.writeFileSync(path.join(root, file), files[file]);
  return stale;
}

function main(args) {
  if (args.includes('--check')) {
    const files = buildVocabRuntime();
    const stale = staleFiles(files);
    if (stale.length) {
      console.error('Stale generated vocabulary runtime: ' + stale.join(', ') + '. Run npm run build:vocab-runtime.');
      process.exit(1);
    }
    console.log('Vocabulary runtime is up to date (' + Object.keys(files).join(', ') + ').');
    return;
  }
  const stale = writeVocabRuntime();
  console.log(stale.length ? 'Wrote ' + stale.join(', ') : 'Vocabulary runtime already up to date.');
}

if (require.main === module) main(process.argv.slice(2));
module.exports = { SOURCE_FILES, RUNTIME_FILE, DETAILS_FILE, buildVocabRuntime, writeVocabRuntime, loadMergedVocabulary };
